svg.script:
(function(){
  function react(el){
    if(!el) return;
    el.classList.remove('student-react102');
    void el.getBoundingClientRect();
    el.classList.add('student-react102');
    setTimeout(function(){el.classList.remove('student-react102');},480);
  }
  document.querySelectorAll('.student-hotspot102').forEach(function(h){
    h.addEventListener('pointerdown',function(e){
      e.preventDefault();
      react(document.getElementById(h.getAttribute('data-target')));
    });
  });
})();
